import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';

const FAKE_ASSETS_By_ID = {
  // populated by fakeFile() calls
};

/**
 * A "File" asset -- title/url come from the asset itself (the same `name`/
 * `url` fields confirmed working for `card`'s own resolveUri usage), file
 * size is read from a nested `attributes` object (matching the real
 * MatrixAssetSchema shape confirmed via `card`'s own resolved-asset mocks),
 * and description is read from the `page-description` metadata field
 * (per explicit user correction -- see document.spec.md assumption 3).
 * File type/icon is derived from the url's own extension, not a separate
 * field.
 */
function fakeFile({ id, name, url, fileSizeReadable, description }) {
  const asset = {
    id: String(id),
    type: 'file',
    name,
    url,
    attributes: {
      file_size_readable: fileSizeReadable,
    },
    metadata: description ? { 'page-description': [description] } : {},
  };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

fakeFile({
  id: 4001,
  name: 'Annual Report 2025',
  url: 'https://example.com/files/annual-report-2025.docx',
  fileSizeReadable: '182 KB',
  description: 'The full annual report, covering performance, budget, and community outcomes for the year.',
});
fakeFile({
  id: 4002,
  name: 'Budget Summary',
  url: 'https://example.com/files/budget-summary.xlsx',
  fileSizeReadable: '2.4 MB',
});
fakeFile({
  id: 4003,
  name: 'Community Consultation Guidelines',
  url: 'https://example.com/files/consultation-guidelines.pdf',
  fileSizeReadable: '946 KB',
  description: 'Guidelines for participating in the community consultation process.',
});
fakeFile({
  id: 4004,
  name: 'Stakeholder Presentation',
  url: 'https://example.com/files/stakeholder-presentation.pptx',
  fileSizeReadable: '4.8 MB',
});

/**
 * This component resolves every selected asset at render time via
 * info.fns.resolveUri(uri) -- confirmed (via the same mechanism proven
 * against a real live Squiz DXP backend for `card`) to wrap its result in a
 * { ok, data } envelope. This Storybook fake is a separate,
 * project-controlled mock that exists purely so the resolution *logic* in
 * main.js can be verified here without a real Matrix backend.
 */
const mockInfo = squizInfoMock({
  mock: {
    resolveUri(uri) {
      const assetId = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)/.exec(String(uri ?? ''))?.[1];
      return { ok: true, data: FAKE_ASSETS_By_ID[assetId] ?? null };
    },
  },
});

/**
 * "Show code" can't dynamically capture our output: the shared
 * squizStoryRenderer wraps it in lit's until() because main() is async
 * (per the DXP edge contract), but Storybook's web-components source
 * decorator reads the rendered container's innerHTML synchronously, before
 * that promise resolves -- so dynamic capture always sees an empty result.
 * Precomputing the real HTML here and handing it to Storybook explicitly
 * is the only reliable way to show it.
 */
const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp components/Document',
  parameters: {
    layout: 'padded',
  },
};

const defaultArgs = {
  assets: [
    'matrix-asset://ntg/4001',
    'matrix-asset://ntg/4003',
    'matrix-asset://ntg/4002',
    'matrix-asset://ntg/4004',
  ],
};
const defaultHtml = await squiz.markup(defaultArgs, mockInfo);

export const Default = {
  render: (args) => squiz(args, mockInfo),
  args: defaultArgs,
  argTypes: {
    assets: {
      control: 'object',
      description: 'Array of matrix-asset-uri strings. Only these demo URIs resolve to anything in this Storybook preview (mocked): matrix-asset://ntg/4001 through /4004.',
    },
    download: { control: 'boolean' },
  },
  parameters: {
    docs: {
      description: { story: 'Multiple selected documents -- one card per asset, in the order selected.' },
      source: { code: defaultHtml, language: 'html', type: 'code' },
    },
  },
};

